[CmdletBinding()]
param([Parameter(Mandatory = $true)][string]$RequestPath)

$ErrorActionPreference = 'Stop'
$OutputEncoding = [Console]::OutputEncoding = [Text.UTF8Encoding]::new($false)
$root = [IO.Path]::GetFullPath((Get-Location).Path).TrimEnd('\') + '\'
$requestFull = (Resolve-Path -LiteralPath $RequestPath -ErrorAction Stop).Path
if (-not $requestFull.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) { throw 'RequestPath must remain under the project root.' }
& (Join-Path (Get-Location) 'ES/Automation/WebPageStudio/Test-ESWebPageStudioRequest.ps1') -RequestPath $requestFull | Out-Null
$request = Get-Content -Raw -Encoding UTF8 -LiteralPath $requestFull | ConvertFrom-Json
if ([bool]$request.network.enabled -or [string]$request.backend.mode -ne 'mock-contract-only') {
    throw 'Static HTML generation cannot execute a network or service-backed request. Use a dedicated authorized backend adapter.'
}
$relativeOutput = [string]$request.output.outputDirectory
if ([IO.Path]::IsPathRooted($relativeOutput) -or $relativeOutput -match '(^|[/\\])\.\.([/\\]|$)') { throw 'Output directory must be project-relative.' }
$output = [IO.Path]::GetFullPath((Join-Path (Get-Location) $relativeOutput))
if (-not $output.StartsWith($root, [StringComparison]::OrdinalIgnoreCase)) { throw 'Output directory must remain under the project root.' }
if (Test-Path -LiteralPath $output) { throw "Refusing to overwrite existing output directory: $output" }
New-Item -ItemType Directory -Path $output -Force | Out-Null

$title = [Net.WebUtility]::HtmlEncode([string]$request.objective)
$audience = [Net.WebUtility]::HtmlEncode([string]$request.audience)
$action = [Net.WebUtility]::HtmlEncode([string]$request.primaryAction)
$language = if ($request.PSObject.Properties['language']) { [string]$request.language } elseif ([string]$request.objective -match '[\u4e00-\u9fff]') { 'zh-CN' } else { 'en' }
if ($language -notin @('en','zh-CN','ar')) { throw 'language must be en, zh-CN, or ar.' }
$direction = if ($language -eq 'ar') { 'rtl' } else { 'ltr' }
$pageKind = [string]$request.pageKind
$body = if ($pageKind -eq 'dashboard') {
@"
<a class="skip-link" href="#main-content">Skip to content</a><main id="main-content" class="shell dashboard" data-page-kind="dashboard" data-locale="$language" itemscope itemtype="https://schema.org/WebPage">
  <header class="topbar"><div class="brand"><span class="mark" aria-hidden="true">ES</span><span>WebPageStudio</span></div><span class="status"><i aria-hidden="true"></i> Local preview</span></header>
  <section class="intro"><p class="eyebrow">OPERATIONS / $audience</p><h1 itemprop="name">$title</h1><p class="lede" itemprop="description">A focused command surface for the metrics and decisions that matter now.</p></section>
  <section class="metric-grid"><article><span>Signal health</span><strong>98.4%</strong><small>+4.8% this cycle</small></article><article><span>Active flows</span><strong>24</strong><small>8 need attention</small></article><article><span>Response time</span><strong>142ms</strong><small>18ms faster</small></article><article><span>Coverage</span><strong>86%</strong><small>Across 12 regions</small></article></section>
  <section class="panel" aria-labelledby="momentum-title"><div class="panel-head"><div><span class="eyebrow">LIVE VIEW</span><h2 id="momentum-title">System momentum</h2><p class="state-note" role="status" aria-live="polite">Static preview - data is illustrative</p></div><button type="button" aria-describedby="momentum-title">$action</button></div><div class="bars" aria-label="Weekly momentum illustration"><b style="--v:74%"><i>Mon</i></b><b style="--v:58%"><i>Tue</i></b><b style="--v:88%"><i>Wed</i></b><b style="--v:66%"><i>Thu</i></b><b style="--v:94%"><i>Fri</i></b><b style="--v:81%"><i>Sat</i></b><b style="--v:96%"><i>Sun</i></b></div></section>
  <details class="state-gallery"><summary>View loading, empty and error states</summary><div class="state-card" role="status" aria-live="polite"><strong>Loading state</strong><span>Preparing the next data snapshot...</span></div><div class="state-card"><strong>Empty state</strong><span>No records are available for this filter.</span></div><div class="state-card state-error" role="alert"><strong>Error state</strong><span>We could not refresh this view. Try again later.</span></div></details>
  <footer><span>Updated just now</span><span>STATIC / NO NETWORK</span></footer>
</main>
"@
} else {
@"
<a class="skip-link" href="#main-content">Skip to content</a><main id="main-content" class="shell marketing" data-page-kind="marketing" data-locale="$language" itemscope itemtype="https://schema.org/WebPage">
  <header class="topbar"><div class="brand"><span class="mark" aria-hidden="true">ES</span><span>WebPageStudio</span></div><nav aria-label="Primary navigation"><a href="#signal">Signal</a><a href="#proof">Proof</a><a class="nav-action" href="#start">$action</a></nav></header>
  <section class="hero"><div class="hero-copy"><p class="eyebrow">DESIGNED FOR $audience</p><h1 itemprop="name">$title</h1><p class="lede" itemprop="description">Turn complex intent into a clear, confident experience with a responsive system built for momentum.</p><a class="primary" href="#start">$action <span>&#8599;</span></a></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="core"><span>01</span><strong>READY</strong></div></div></section>
  <section id="signal" class="signal"><div><span class="eyebrow">THE SIGNAL</span><h2>Less noise.<br><em>More signal.</em></h2></div><p>Every surface is arranged around a single next move. Quiet structure, deliberate contrast and enough room for the idea to land.</p></section>
  <section id="proof" class="proof"><article><span>01</span><h3>Clarity at speed</h3><p>Hierarchy that keeps important decisions visible at a glance.</p></article><article><span>02</span><h3>Built to adapt</h3><p>Responsive behavior is part of the design, not an afterthought.</p></article><article><span>03</span><h3>Ready to ship</h3><p>Self-contained HTML/CSS with a clean path to your next revision.</p></article></section>
  <section id="start" class="closing"><span class="eyebrow">YOUR NEXT MOVE</span><h2>Make the first impression<br><em>unmistakable.</em></h2><form class="capture" action="#start" method="get"><label for="contact-email">Get the next update</label><div><input id="contact-email" name="email" type="email" autocomplete="email" required placeholder="you@example.com" aria-describedby="contact-help"><button type="submit">$action</button></div><small id="contact-help">Static preview only; no network request is sent.</small></form><details class="state-gallery"><summary>View submission states</summary><div class="state-card" role="status" aria-live="polite"><strong>Loading state</strong><span>Preparing your request...</span></div><div class="state-card"><strong>Empty state</strong><span>No update is available yet.</span></div><div class="state-card state-error" role="alert"><strong>Error state</strong><span>Submission is unavailable in static preview mode.</span></div></details></section>
  <footer><span>STATIC / NO NETWORK</span><span>ES WebPageStudio</span></footer>
</main>
"@
}
$localePath = Join-Path (Get-Location) 'ES/Automation/WebPageStudio/locale-resources.json'
$localeData = Get-Content -Raw -Encoding UTF8 -LiteralPath $localePath | ConvertFrom-Json
$localeCopy = $localeData.locales.PSObject.Properties[$language].Value
if ($null -eq $localeCopy) { $localeCopy = $localeData.locales.en }
$replacements = [ordered]@{
    'Skip to content' = [string]$localeCopy.skip; 'Local preview' = [string]$localeCopy.preview;
    'Signal' = [string]$localeCopy.signal; 'Proof' = [string]$localeCopy.proof;
    'YOUR NEXT MOVE' = ([string]$localeCopy.next).ToUpperInvariant(); 'Loading state' = [string]$localeCopy.loading;
    'Empty state' = [string]$localeCopy.empty; 'Error state' = [string]$localeCopy.error;
    'View loading, empty and error states' = [string]$localeCopy.states;
    'Static preview - data is illustrative' = [string]$localeCopy.static
}
foreach ($key in $replacements.Keys) { $body = $body.Replace($key, $replacements[$key]) }
$html = @"
<!doctype html>
<html lang="$language" dir="$direction"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="$title - responsive ES WebPageStudio experience"><meta name="generator" content="ES WebPageStudio"><meta name="application-name" content="ES WebPageStudio"><meta name="robots" content="index,follow"><meta property="og:type" content="website"><meta property="og:title" content="$title"><meta property="og:description" content="$title - responsive ES WebPageStudio experience"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; manifest-src 'self'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'"><link rel="icon" href="icon.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="icon.svg"><link rel="manifest" href="site.webmanifest"><meta name="color-scheme" content="dark light"><meta name="theme-color" content="#101516" media="(prefers-color-scheme: dark)"><meta name="theme-color" content="#f4f7f5" media="(prefers-color-scheme: light)"><meta name="referrer" content="no-referrer"><title>$title</title>
<style>
:root{--ink:#f4f7f5;--muted:#9aa7a3;--bg:#101516;--panel:#172021;--line:#2b3938;--cyan:#75e1d1;--lime:#d1f36a;--pink:#f28a9a;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);letter-spacing:0}.skip-link{position:fixed;left:12px;top:8px;z-index:10;transform:translateY(-160%);padding:10px 14px;background:var(--lime);color:#172021;font-weight:800;text-decoration:none}.skip-link:focus{transform:translateY(0)}:where(a,button,input,select,textarea):focus-visible{outline:3px solid var(--lime);outline-offset:3px}.shell{width:min(1180px,calc(100% - 48px));margin:auto}.topbar{height:92px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;gap:12px;font-size:14px;font-weight:700;letter-spacing:.08em}.mark{display:grid;place-items:center;width:34px;height:34px;border:1px solid var(--cyan);color:var(--cyan);font-size:11px}.status{color:var(--muted);font-size:11px;letter-spacing:.08em;text-transform:uppercase}.status i{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--lime);margin-right:8px}nav{display:flex;gap:28px;align-items:center}nav a{color:var(--muted);text-decoration:none;font-size:12px}nav a:hover{color:var(--ink)}.nav-action{border:1px solid var(--line);padding:11px 16px;color:var(--ink)}.eyebrow{color:var(--cyan);font-size:10px;letter-spacing:.18em;font-weight:700}.lede{color:var(--muted);font-size:17px;line-height:1.6;max-width:520px}.hero{min-height:650px;display:grid;grid-template-columns:1.1fr .9fr;align-items:center;gap:40px}.hero h1{font-size:clamp(48px,7vw,96px);line-height:.94;max-width:720px;margin:20px 0 26px}.primary{display:inline-flex;gap:20px;align-items:center;margin-top:28px;padding:15px 19px;background:var(--lime);color:#172021;text-decoration:none;font-weight:800;font-size:13px}.primary span{font-size:18px}.hero-art{height:390px;position:relative;border:1px solid var(--line);overflow:hidden;background:#131c1c}.orbit{position:absolute;border:1px solid #456360;border-radius:50%;left:50%;top:50%;transform:translate(-50%,-50%) rotate(-18deg)}.orbit-a{width:360px;height:190px}.orbit-b{width:250px;height:330px;transform:translate(-50%,-50%) rotate(38deg);border-color:#6c4c58}.core{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);display:grid;gap:8px;text-align:center;border:1px solid var(--cyan);padding:28px 34px;background:#172021}.core span{color:var(--cyan);font-size:10px}.core strong{font-size:18px;letter-spacing:.16em}.signal{display:grid;grid-template-columns:1fr 1fr;gap:80px;border-top:1px solid var(--line);padding:110px 0}.signal h2,.closing h2{font-size:clamp(38px,5vw,68px);line-height:1;margin:18px 0}.signal em,.closing em{color:var(--pink);font-style:normal}.signal p{color:var(--muted);font-size:19px;line-height:1.6;max-width:470px}.proof{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line)}.proof article{background:var(--bg);padding:34px;min-height:220px}.proof span{color:var(--lime);font-size:11px}.proof h3{font-size:22px;margin:48px 0 12px}.proof p{color:var(--muted);line-height:1.55}.closing{padding:150px 0;text-align:center;border-bottom:1px solid var(--line)}.closing h2{margin-left:auto;margin-right:auto}.closing .primary{margin-top:12px}.shell footer{display:flex;justify-content:space-between;padding:24px 0;color:#687572;font-size:10px;letter-spacing:.12em}.dashboard .intro{padding:70px 0 42px}.dashboard h1{font-size:clamp(40px,6vw,76px);line-height:1;margin:16px 0}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line)}.metric-grid article{background:var(--bg);padding:22px}.metric-grid span,.metric-grid small{display:block;color:var(--muted);font-size:11px}.metric-grid strong{display:block;font-size:36px;margin:28px 0 10px}.metric-grid small{color:var(--lime)}.panel{margin-top:42px;background:var(--panel);border:1px solid var(--line);padding:28px}.panel-head{display:flex;justify-content:space-between;align-items:flex-start}.panel h2{margin:10px 0 0;font-size:26px}.panel button{border:1px solid var(--cyan);background:transparent;color:var(--cyan);padding:10px 14px;font-weight:700}.bars{height:250px;display:flex;align-items:end;gap:20px;border-bottom:1px solid var(--line);padding:28px 0 0}.bars b{height:var(--v);flex:1;background:var(--cyan);min-width:18px;position:relative}.bars b:nth-child(2n){background:var(--pink)}.bars i{position:absolute;top:calc(100% + 10px);font-style:normal;color:var(--muted);font-size:10px}.dashboard footer{margin-top:18px}.dashboard footer span:last-child{color:var(--lime)}@media(max-width:760px){.shell{width:min(100% - 32px,540px)}.topbar{height:76px}nav a:not(.nav-action){display:none}.hero{grid-template-columns:1fr;min-height:auto;padding:72px 0}.hero-art{height:300px}.signal{grid-template-columns:1fr;gap:22px;padding:80px 0}.proof,.metric-grid{grid-template-columns:1fr}.proof article{min-height:0}.closing{padding:100px 0}.bars{gap:8px}.panel{padding:18px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
</style><style>
/* Theme and user-preference layer: static, dependency-free, and deterministic. */
@media (prefers-color-scheme: light){:root{--ink:#172021;--muted:#536562;--bg:#f4f7f5;--panel:#ffffff;--line:#c8d6d2;--cyan:#087f78;--lime:#8ab51f;--pink:#b63d5a}.hero-art{background:#e8f0ed}.core{background:#ffffff}}
.capture{display:grid;gap:10px;max-width:520px;margin:36px auto 0;text-align:left}.capture label{font-size:12px;font-weight:700;color:var(--ink)}.capture>div{display:flex;gap:10px}.capture input{min-width:0;flex:1;border:1px solid var(--line);background:var(--panel);color:var(--ink);padding:13px 14px;font:inherit}.capture button{border:0;background:var(--lime);color:#172021;padding:13px 16px;font-weight:800;cursor:pointer}.capture small,.state-note{color:var(--muted);font-size:11px;line-height:1.5}.state-gallery{margin-top:28px;border-top:1px solid var(--line);padding-top:16px;color:var(--muted);font-size:12px}.state-gallery summary{cursor:pointer;color:var(--cyan);font-weight:700}.state-card{display:grid;gap:6px;margin-top:12px;padding:14px;border:1px solid var(--line);background:var(--panel)}.state-card strong{color:var(--ink)}.state-card span{color:var(--muted)}.state-error{border-color:var(--pink)}@media print{body{background:#fff;color:#111}.topbar nav,.hero-art,.primary,.capture,footer{display:none}.shell{width:100%}.lede,.signal p,.proof p,.metric-grid span,.metric-grid small{color:#333}}@media (forced-colors:active){*:focus-visible{outline:2px solid CanvasText}.primary,.capture button{border:1px solid ButtonText}.mark,.hero-art,.panel{border-color:ButtonText}}
</style></head><body><div id="top">$body</div></body></html>
"@
$html = $html.Replace('<meta name="robots" content="index,follow">', '<meta name="robots" content="index,follow"><link rel="canonical" href="./"><meta property="og:url" content="./"><meta property="og:image" content="./icon.svg"><meta name="twitter:card" content="summary"><meta name="twitter:title" content="$title"><meta name="twitter:description" content="$title - responsive ES WebPageStudio experience"><meta name="twitter:image" content="./icon.svg">')
$html = $html.Replace('$title', $title)
$publicBaseUrl = if ($request.PSObject.Properties['publicBaseUrl']) { ([string]$request.publicBaseUrl).TrimEnd('/') } else { '' }
if ($publicBaseUrl) { $html = $html.Replace('href="./"', 'href="' + $publicBaseUrl + '/"').Replace('content="./"', 'content="' + $publicBaseUrl + '/"').Replace('content="./icon.svg"', 'content="' + $publicBaseUrl + '/icon.svg"') }
$entry = Join-Path $output ([string]$request.output.entryFile)
[IO.File]::WriteAllText($entry, $html, [Text.UTF8Encoding]::new($false))
$icon='<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512"><rect width="512" height="512" rx="96" fill="#101516"/><path d="M112 128h288v64H176v64h176v64H176v64h224v64H112z" fill="#d1f36a"/></svg>';[IO.File]::WriteAllText((Join-Path $output 'icon.svg'),$icon,[Text.UTF8Encoding]::new($false));[ordered]@{id='./';name=[string]$request.objective;short_name='ES WebPageStudio';start_url='./';scope='./';display='standalone';lang=$language;dir=$direction;theme_color='#101516';background_color='#101516';icons=@([ordered]@{src='./icon.svg';sizes='192x192 512x512';type='image/svg+xml';purpose='any maskable'});description="$title - responsive ES WebPageStudio experience"} | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath (Join-Path $output 'site.webmanifest') -Encoding utf8
[IO.File]::WriteAllText((Join-Path $output 'robots.txt'), "User-agent: *`nAllow: /`n", [Text.UTF8Encoding]::new($false))
$sitemapChangeFreq = if ($request.PSObject.Properties['sitemap']) { [string]$request.sitemap.changefreq } else { 'weekly' }
$sitemapPriority = if ($request.PSObject.Properties['sitemap']) { ([double]$request.sitemap.priority).ToString('0.0',[Globalization.CultureInfo]::InvariantCulture) } else { '0.8' }
$sitemapPaths = if ($request.PSObject.Properties['sitemap'] -and $request.sitemap.paths) { @($request.sitemap.paths) } else { @('./') }
$sitemapUrls = $sitemapPaths | ForEach-Object { if ($publicBaseUrl) { $publicBaseUrl + '/' + ([string]$_).TrimStart('./') } else { [string]$_ } }
$sitemapRows = ($sitemapUrls | ForEach-Object { '<url><loc>' + $_ + '</loc><changefreq>' + $sitemapChangeFreq + '</changefreq><priority>' + $sitemapPriority + '</priority></url>' }) -join ''
[IO.File]::WriteAllText((Join-Path $output 'sitemap.xml'), ('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' + $sitemapRows + '</urlset>'), [Text.UTF8Encoding]::new($false))
[pscustomobject]@{ status = 'static-generated'; entryFile = $entry; pageKind = $pageKind; network = [bool]$request.network.enabled; runtimeStatus = 'runtime-not-run' }
